package affected

import (
	"errors"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// dynreads.tsv is GENERATED by `cigate plan-dynreads` from the AST: one row per Go file holding a read, open or walk
// call whose path the tool cannot resolve to a repository path, or a read of a path a walk hands its callback:
//
//	package<TAB>site<TAB>classes
//
// classes is the classes of the walk roots those callback paths come from, or `unexpressed` when a call reads a path the
// tool cannot bound. Paths the tool resolves are not rows: a temp dir or the package's own directory is not a repo read,
// and a repository path (a constant, a constant expression, or a root locator joined with constant ".."-free parts) is a
// literal read that reads.tsv must cover. The planner selects the package of an `unexpressed` row on every non-Go change
// (and of any code-site row, the tests of every package that links it), so no such change plans NONE while one exists;
// tables that differ from the generated ones plan FULL, and plan-reads fails the difference. A hand edit may only narrow
// an `unexpressed` dynreads row to a class list (a reviewed diff). The planner's own package is left out: its reads run
// in the always-run static leg.
const (
	dynReadsFile   = "dynreads.tsv"
	dynUnexpressed = "unexpressed"
	dynExcludedPkg = "internal/cigates/affected"
)

type dynRow struct {
	pkg, site string
	classes   []string
	line      int
}

func (d dynRow) scope() string {
	if strings.HasSuffix(d.site, "_test.go") {
		return scopeTest
	}
	return scopeCode
}

func loadDynReads(dir string, known map[string]bool) ([]dynRow, error) {
	rows, lines, err := readTSV(filepath.Join(dir, dynReadsFile), 3)
	if err != nil {
		return nil, err
	}
	var out []dynRow
	seen := map[string]bool{}
	for i, r := range rows {
		d := dynRow{pkg: r[0], site: r[1], classes: splitList(r[2]), line: lines[i]}
		where := fmt.Sprintf("%s:%d", dynReadsFile, d.line)
		if path.Clean(d.pkg) != d.pkg || strings.HasPrefix(d.pkg, "/") || strings.HasPrefix(d.pkg, "../") {
			return nil, fmt.Errorf("%s: package %q is not a clean repository path", where, d.pkg)
		}
		if !strings.HasSuffix(d.site, ".go") || strings.Contains(d.site, "/") {
			return nil, fmt.Errorf("%s: site %q is not a Go file base name", where, d.site)
		}
		for _, c := range d.classes {
			if c == dynUnexpressed && len(d.classes) == 1 {
				continue
			}
			if !known[c] {
				return nil, fmt.Errorf("%s: class %q is not in %s", where, c, classesFile)
			}
		}
		k := d.pkg + "/" + d.site
		if seen[k] {
			return nil, fmt.Errorf("%s: %s already has a row", where, k)
		}
		seen[k] = true
		out = append(out, d)
	}
	return out, nil
}

func (d dynRow) unexpressed() bool { return len(d.classes) == 1 && d.classes[0] == dynUnexpressed }

func (d dynRow) cell() string {
	if len(d.classes) == 0 {
		return "-"
	}
	return strings.Join(d.classes, ",")
}

// Kinds of a path expression (pathKind):
//
//	const    a constant value (literals, package string constants, +, Join/Clean of those): resolved against the package dir
//	repo     a repository path: a root locator (repoRoot(t), RepoRoot, ...) joined with constant ".."-free parts
//	temp     rooted at t.TempDir/os.MkdirTemp/os.CreateTemp with constant ".."-free parts after the root
//	own      the package's own directory (runtime.Caller's file dir) with constant ".."-free parts after it
//	ownfile  runtime.Caller's file
//	walkpath a path a walk hands its callback (root and depth of that walk), with constant ".."-free parts after it
//	dyn      anything else
const (
	kindConst    = "const"
	kindRepo     = "repo"
	kindTemp     = "temp"
	kindOwn      = "own"
	kindOwnFile  = "ownfile"
	kindWalkPath = "walkpath"
	kindDyn      = "dyn"
)

type pathInfo struct {
	kind  string
	value string // const: the folded value; repo/walkpath: the repository path (walkpath: the walk root)
	depth string // walkpath: the walk's depth
}

var tempRoot = map[string]bool{"t.TempDir": true, "b.TempDir": true, "tb.TempDir": true, "f.TempDir": true, "os.MkdirTemp": true, "os.TempDir": true}

type dynScope struct {
	parent *dynScope
	locals map[string]*pathInfo // nil value: assignments disagree
}

func (sc *dynScope) lookup(name string) (*pathInfo, bool) {
	for s := sc; s != nil; s = s.parent {
		if v, ok := s.locals[name]; ok {
			return v, true
		}
	}
	return nil, false
}

type dynCtx struct {
	pkgDir    string
	constVals map[string]string // package string constants with a literal value
}

// fold evaluates a constant string expression.
func (c *dynCtx) fold(e ast.Expr) (string, bool) {
	switch x := e.(type) {
	case *ast.BasicLit:
		if x.Kind != token.STRING {
			return "", false
		}
		v, err := strconv.Unquote(x.Value)
		return v, err == nil
	case *ast.Ident:
		v, ok := c.constVals[x.Name]
		return v, ok
	case *ast.ParenExpr:
		return c.fold(x.X)
	case *ast.BinaryExpr:
		if x.Op != token.ADD {
			return "", false
		}
		a, ok1 := c.fold(x.X)
		b, ok2 := c.fold(x.Y)
		return a + b, ok1 && ok2
	case *ast.CallExpr:
		switch callName(x.Fun) {
		case "filepath.Join", "path.Join":
			var parts []string
			for _, a := range x.Args {
				v, ok := c.fold(a)
				if !ok {
					return "", false
				}
				parts = append(parts, v)
			}
			return path.Join(parts...), true
		case "filepath.Clean", "path.Clean", "filepath.FromSlash", "filepath.ToSlash":
			if len(x.Args) == 1 {
				v, ok := c.fold(x.Args[0])
				if ok && callName(x.Fun) != "filepath.FromSlash" && callName(x.Fun) != "filepath.ToSlash" {
					v = path.Clean(v)
				}
				return v, ok
			}
		}
	}
	return "", false
}

// resolve places a constant path, relative to the package directory as a test's working directory is: own (inside the
// package), repo (another repository path), or outside (absolute, or above the repository root).
func (c *dynCtx) resolve(v string) pathInfo {
	if v == "" || strings.HasPrefix(v, "/") {
		return pathInfo{kind: kindDyn}
	}
	r := path.Clean(c.pkgDir + "/" + v)
	switch {
	case r == ".." || strings.HasPrefix(r, "../"):
		return pathInfo{kind: kindDyn}
	case r == c.pkgDir || strings.HasPrefix(r, c.pkgDir+"/"):
		return pathInfo{kind: kindOwn}
	}
	return pathInfo{kind: kindRepo, value: r}
}

func safePart(v string) bool {
	return !strings.Contains(v, "..") && !strings.HasPrefix(v, "/")
}

func (c *dynCtx) pathKind(e ast.Expr, sc *dynScope) pathInfo {
	if v, ok := c.fold(e); ok {
		return pathInfo{kind: kindConst, value: v}
	}
	switch x := e.(type) {
	case *ast.ParenExpr:
		return c.pathKind(x.X, sc)
	case *ast.Ident:
		if v, ok := sc.lookup(x.Name); ok && v != nil {
			return *v
		}
		return pathInfo{kind: kindDyn}
	case *ast.CallExpr:
		name := callName(x.Fun)
		short := name
		if i := strings.LastIndexByte(name, '.'); i >= 0 {
			short = name[i+1:]
		}
		switch {
		case tempRoot[name]:
			return pathInfo{kind: kindTemp}
		case rootLocator.MatchString(short):
			return pathInfo{kind: kindRepo, value: "."}
		}
		if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Name" && len(x.Args) == 0 {
			if id, ok := sel.X.(*ast.Ident); ok {
				if v, _ := sc.lookup(id.Name); v != nil && v.kind == kindTemp {
					return pathInfo{kind: kindTemp}
				}
			}
		}
		switch name {
		case "filepath.Join", "path.Join":
			if len(x.Args) == 0 {
				return pathInfo{kind: kindDyn}
			}
			root := c.pathKind(x.Args[0], sc)
			var rest []string
			for _, a := range x.Args[1:] {
				v, ok := c.fold(a)
				if !ok || !safePart(v) {
					return pathInfo{kind: kindDyn}
				}
				rest = append(rest, v)
			}
			switch root.kind {
			case kindRepo:
				return pathInfo{kind: kindRepo, value: path.Join(append([]string{root.value}, rest...)...)}
			case kindTemp, kindOwn:
				return root
			case kindWalkPath:
				return root
			}
			return pathInfo{kind: kindDyn}
		case "filepath.Dir", "path.Dir":
			if len(x.Args) == 1 {
				in := c.pathKind(x.Args[0], sc)
				switch in.kind {
				case kindOwnFile:
					return pathInfo{kind: kindOwn}
				case kindTemp:
					return in
				case kindRepo:
					if in.value != "." {
						return pathInfo{kind: kindRepo, value: path.Dir(in.value)}
					}
				}
			}
			return pathInfo{kind: kindDyn}
		case "filepath.Clean", "path.Clean", "filepath.Abs", "filepath.FromSlash", "filepath.ToSlash":
			if len(x.Args) == 1 {
				return c.pathKind(x.Args[0], sc)
			}
		}
	}
	return pathInfo{kind: kindDyn}
}

// assignedKinds folds the locals of one function body: a local has the kind of every value assigned to it, and none when
// two assignments disagree. runtime.Caller's file result is ownfile; os.MkdirTemp/CreateTemp results are temp.
func (c *dynCtx) assignedKinds(body ast.Node, sc *dynScope) {
	set := func(name string, v pathInfo) {
		if name == "_" {
			return
		}
		if old, ok := sc.locals[name]; ok && (old == nil || *old != v) {
			sc.locals[name] = nil
			return
		}
		sc.locals[name] = &v
	}
	for pass := 0; pass < 3; pass++ {
		ast.Inspect(body, func(n ast.Node) bool {
			switch a := n.(type) {
			case *ast.AssignStmt:
				if len(a.Rhs) == 1 && len(a.Lhs) > 1 {
					if call, ok := a.Rhs[0].(*ast.CallExpr); ok {
						switch callName(call.Fun) {
						case "runtime.Caller":
							if id, ok := a.Lhs[1].(*ast.Ident); ok {
								set(id.Name, pathInfo{kind: kindOwnFile})
							}
							return true
						case "os.MkdirTemp", "os.CreateTemp":
							if id, ok := a.Lhs[0].(*ast.Ident); ok {
								set(id.Name, pathInfo{kind: kindTemp})
							}
							return true
						}
					}
					for _, l := range a.Lhs {
						if id, ok := l.(*ast.Ident); ok {
							set(id.Name, pathInfo{kind: kindDyn})
						}
					}
					return true
				}
				for i, l := range a.Lhs {
					if id, ok := l.(*ast.Ident); ok && i < len(a.Rhs) {
						set(id.Name, c.pathKind(a.Rhs[i], sc))
					}
				}
			case *ast.ValueSpec:
				for i, id := range a.Names {
					if i < len(a.Values) {
						set(id.Name, c.pathKind(a.Values[i], sc))
					} else {
						set(id.Name, pathInfo{kind: kindDyn})
					}
				}
			case *ast.RangeStmt:
				for _, e := range []ast.Expr{a.Key, a.Value} {
					if id, ok := e.(*ast.Ident); ok {
						set(id.Name, pathInfo{kind: kindDyn})
					}
				}
			}
			return true
		})
	}
}

// walkDepth: the calls that list one directory, not a tree.
var dirOnlyWalk = map[string]bool{"os.ReadDir": true, "fs.ReadDir": true, "filepath.Glob": true, "fs.Glob": true, "ioutil.ReadDir": true}

var isWalkCall = map[string]bool{
	"filepath.WalkDir": true, "filepath.Walk": true, "filepath.Glob": true, "os.ReadDir": true, "os.DirFS": true,
	"fs.WalkDir": true, "fs.ReadDir": true, "fs.Glob": true, "fs.Sub": true, "ioutil.ReadDir": true,
}

// walkRoot resolves the root of a walk call: kind repo with the directory and depth, or own/temp (no row), or dyn.
func (c *dynCtx) walkRoot(call *ast.CallExpr, name string, sc *dynScope) pathInfo {
	if strings.HasPrefix(name, "fs.") {
		return pathInfo{kind: kindDyn}
	}
	in := c.pathKind(call.Args[0], sc)
	depth := depthTree
	if dirOnlyWalk[name] {
		depth = depthDir
	}
	if in.kind == kindConst {
		in = c.resolve(in.value)
	}
	if in.kind == kindWalkPath {
		return pathInfo{kind: kindRepo, value: in.value, depth: depthTree}
	}
	if in.kind == kindRepo && name == "filepath.Glob" {
		segs := strings.Split(in.value, "/")
		for i, s := range segs {
			if strings.ContainsAny(s, "*?[") {
				root := path.Join(segs[:i]...)
				if root == "" {
					root = "."
				}
				if i < len(segs)-1 {
					depth = depthTree
				}
				return pathInfo{kind: kindRepo, value: root, depth: depth}
			}
		}
	}
	in.depth = depth
	return in
}

// dynamicReads classifies every read, open or walk call of a file whose path is not a plain literal: a resolved
// repository path becomes a literal read, a walk becomes a walk record, anything unbounded a dynamic read.
func dynamicReads(fset *token.FileSet, f *ast.File, rel string, consts map[string]bool, constVals map[string]string, top map[string]bool) []Read {
	pkg := path.Dir(rel)
	test := strings.HasSuffix(rel, "_test.go")
	c := &dynCtx{pkgDir: pkg, constVals: constVals}
	var out []Read
	at := func(n ast.Node) int { return fset.Position(n.Pos()).Line }
	record := func(call *ast.CallExpr, name string, sc *dynScope) {
		if !dynamicCalls[name] || len(call.Args) == 0 {
			return
		}
		arg := call.Args[0]
		if strings.HasPrefix(name, "fs.") && len(call.Args) > 1 {
			arg = call.Args[1]
		}
		lit := name + "(" + exprText(fset, arg) + ")"
		if isWalkCall[name] {
			r := c.walkRoot(call, name, sc)
			switch r.kind {
			case kindRepo:
				out = append(out, Read{Package: pkg, File: rel, Line: at(call), Test: test, Walk: true, Root: r.value, Depth: r.depth, Literal: lit})
			case kindDyn:
				out = append(out, Read{Package: pkg, File: rel, Line: at(call), Test: test, Walk: true, Root: walkUnexpressed, Depth: "-", Literal: lit})
			}
			return
		}
		in := c.pathKind(arg, sc)
		if in.kind == kindConst {
			if _, plain := arg.(*ast.BasicLit); plain {
				return // the literal scan reads it
			}
			in = c.resolve(in.value)
		}
		switch in.kind {
		case kindRepo:
			if in.value != "." && top[strings.SplitN(in.value, "/", 2)[0]] {
				out = append(out, Read{Package: pkg, File: rel, Line: at(call), Test: test, Path: in.value, Literal: lit})
			}
		case kindWalkPath:
			out = append(out, Read{Package: pkg, File: rel, Line: at(call), Test: test, Dynamic: true, Kind: kindWalkPath, Root: in.value, Depth: in.depth, Literal: lit})
		case kindDyn:
			out = append(out, Read{Package: pkg, File: rel, Line: at(call), Test: test, Dynamic: true, Kind: kindDyn, Literal: lit})
		}
	}
	var visit func(n ast.Node, sc *dynScope)
	visit = func(n ast.Node, sc *dynScope) {
		ast.Inspect(n, func(m ast.Node) bool {
			if m == n {
				return true
			}
			switch x := m.(type) {
			case *ast.FuncLit:
				inner := &dynScope{parent: sc, locals: map[string]*pathInfo{}}
				c.assignedKinds(x.Body, inner)
				visit(x.Body, inner)
				return false
			case *ast.CallExpr:
				name := callName(x.Fun)
				if (name == "filepath.WalkDir" || name == "filepath.Walk" || name == "fs.WalkDir") && len(x.Args) > 1 {
					if lit, ok := x.Args[len(x.Args)-1].(*ast.FuncLit); ok {
						root := c.walkRoot(x, name, sc)
						param := pathInfo{kind: kindDyn}
						switch root.kind {
						case kindRepo:
							param = pathInfo{kind: kindWalkPath, value: root.value, depth: root.depth}
						case kindTemp, kindOwn:
							param = pathInfo{kind: root.kind}
						}
						inner := &dynScope{parent: sc, locals: map[string]*pathInfo{}}
						if len(lit.Type.Params.List) > 0 && len(lit.Type.Params.List[0].Names) > 0 {
							inner.locals[lit.Type.Params.List[0].Names[0].Name] = &param
						}
						c.assignedKinds(lit.Body, inner)
						for _, a := range x.Args[:len(x.Args)-1] {
							visit(a, sc)
						}
						record(x, name, sc)
						visit(lit.Body, inner)
						return false
					}
				}
				record(x, name, sc)
			}
			return true
		})
	}
	for _, d := range f.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		sc := &dynScope{locals: map[string]*pathInfo{}}
		c.assignedKinds(fd.Body, sc)
		visit(fd.Body, sc)
	}
	return out
}

// generate is the walks.tsv and dynreads.tsv the tree calls for, with one sample call per row for messages.
func generate(reads []Read, t *tables, files []string) ([]walkRow, []dynRow, map[string]string) {
	samples := map[string]string{}
	walks := map[string]walkRow{}
	type acc struct {
		classes     map[string]bool
		unexpressed bool
		sample      string
	}
	dyn := map[string]*acc{}
	for _, r := range reads {
		if r.Package == dynExcludedPkg || !(r.Walk || r.Dynamic) {
			continue
		}
		site := path.Base(r.File)
		sample := fmt.Sprintf("%s:%d %s", r.File, r.Line, r.Literal)
		if r.Walk {
			w := walkRow{pkg: r.Package, site: site, root: r.Root, depth: r.Depth}
			if _, ok := walks[w.key()]; !ok {
				if w.root != walkUnexpressed {
					w.classes = t.reachOf(files, w)
				}
				walks[w.key()] = w
				samples[w.key()] = sample
			}
			continue
		}
		k := r.Package + "/" + site
		a := dyn[k]
		if a == nil {
			a = &acc{classes: map[string]bool{}, sample: sample}
			dyn[k] = a
		}
		if r.Kind == kindWalkPath {
			for _, c := range t.reachOf(files, walkRow{root: r.Root, depth: r.Depth}) {
				a.classes[c] = true
			}
			continue
		}
		if !a.unexpressed {
			a.sample = sample
		}
		a.unexpressed = true
	}
	var wout []walkRow
	for _, w := range walks {
		wout = append(wout, w)
	}
	sort.Slice(wout, func(i, j int) bool { return wout[i].key() < wout[j].key() })
	var dout []dynRow
	for k, a := range dyn {
		i := strings.LastIndexByte(k, '/')
		d := dynRow{pkg: k[:i], site: k[i+1:]}
		if a.unexpressed {
			d.classes = []string{dynUnexpressed}
		} else {
			d.classes = sortedKeys(a.classes)
			if len(d.classes) == 0 {
				continue
			}
		}
		dout = append(dout, d)
		samples[k] = a.sample
	}
	sort.Slice(dout, func(i, j int) bool { return dout[i].pkg+"/"+dout[i].site < dout[j].pkg+"/"+dout[j].site })
	return wout, dout, samples
}

// dynDiff compares the checked-in dynreads rows with the generated ones: one line per difference. A checked-in class list
// (or `-`) where the generated row is `unexpressed` is a reviewed narrowing, not a difference.
func dynDiff(generated []dynRow, samples map[string]string, t *tables) []string {
	have := map[string]dynRow{}
	for _, d := range t.dynReads {
		have[d.pkg+"/"+d.site] = d
	}
	var out []string
	for _, g := range generated {
		k := g.pkg + "/" + g.site
		h, ok := have[k]
		delete(have, k)
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("%s: undeclared dynamic read: %s; the generated row is %s\t%s\t%s (cigate plan-dynreads)", g.pkg, samples[k], g.pkg, g.site, g.cell()))
		case h.cell() == g.cell():
		case g.unexpressed() && !h.unexpressed():
		default:
			out = append(out, fmt.Sprintf("%s:%d: %s/%s is %s, the generated row is %s (%s)", dynReadsFile, h.line, g.pkg, g.site, h.cell(), g.cell(), samples[k]))
		}
	}
	for k, h := range have {
		out = append(out, fmt.Sprintf("%s:%d: %s holds no read the generator keeps", dynReadsFile, h.line, k))
	}
	sort.Strings(out)
	return out
}

// allFiles is the tracked files of a git checkout, else every file under root (a plain fixture tree).
func allFiles(root string) ([]string, error) {
	if files := repoFiles(root); files != nil {
		return files, nil
	}
	var out []string
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		out = append(out, filepath.ToSlash(rel))
		return nil
	})
	return out, err
}

// generatedDiff is every difference between the checked-in walks.tsv/dynreads.tsv and the tree.
func generatedDiff(root string, reads []Read, t *tables) ([]string, error) {
	files, err := allFiles(root)
	if err != nil {
		return nil, err
	}
	w, d, samples := generate(reads, t, files)
	return append(walkDiff(w, samples, t), dynDiff(d, samples, t)...), nil
}

// planDynamic is the planner's view: the differences between the generated tables and the tree, read at plan time.
func planDynamic(root string, t *tables) ([]string, error) {
	if _, err := os.Stat(root); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	reads, err := ScanReads(root)
	if err != nil {
		return nil, err
	}
	return generatedDiff(root, reads, t)
}

// PlanDynReads prints the generated walks.tsv and dynreads.tsv for the tree at --root; with --write it writes them into
// the tables directory, keeping every reviewed narrowing of an `unexpressed` dynreads row.
func PlanDynReads(args []string, stdout, stderr io.Writer) int {
	fl := flag.NewFlagSet("plan-dynreads", flag.ContinueOnError)
	fl.SetOutput(stderr)
	root := fl.String("root", "", "repository root")
	tablesDir := fl.String("tables", "", "directory of the tables (default ROOT/internal/cigates/affected)")
	write := fl.Bool("write", false, "write walks.tsv and dynreads.tsv into the tables directory")
	if err := fl.Parse(args); err != nil {
		return 2
	}
	if *root == "" {
		fmt.Fprintln(stderr, "plan-dynreads: --root is required")
		return 2
	}
	dir := *tablesDir
	if dir == "" {
		dir = filepath.Join(*root, filepath.FromSlash(plannerDir))
	}
	t, err := loadTables(dir)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	reads, err := ScanReads(*root)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	files, err := allFiles(*root)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	walks, dyn, _ := generate(reads, t, files)
	narrowed := map[string]dynRow{}
	for _, d := range t.dynReads {
		if !d.unexpressed() {
			narrowed[d.pkg+"/"+d.site] = d
		}
	}
	var wb, db strings.Builder
	wb.WriteString("# GENERATED by `cigate plan-dynreads --root . --write` (walks.go)\n# package\tsite\troot\tdepth\tclasses\n")
	for _, w := range walks {
		wb.WriteString(w.cells() + "\n")
	}
	db.WriteString("# GENERATED by `cigate plan-dynreads --root . --write`; a hand edit may only narrow an `unexpressed` row (dynreads.go)\n# package\tsite\tclasses\n")
	for _, d := range dyn {
		if n, ok := narrowed[d.pkg+"/"+d.site]; ok && d.unexpressed() {
			d = n
		}
		fmt.Fprintf(&db, "%s\t%s\t%s\n", d.pkg, d.site, d.cell())
	}
	if !*write {
		fmt.Fprint(stdout, "== "+walksFile+"\n"+wb.String()+"== "+dynReadsFile+"\n"+db.String())
		return 0
	}
	for name, body := range map[string]string{walksFile: wb.String(), dynReadsFile: db.String()} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			fmt.Fprintln(stderr, err)
			return 1
		}
	}
	fmt.Fprintf(stdout, "plan-dynreads: wrote %d walks row(s) and %d dynreads row(s) to %s\n", len(walks), len(dyn), dir)
	return 0
}

// logDynamicReads writes one line per package with dynreads.tsv rows: its declared classes against the classes the change
// reaches, and whether the change selected it.
func (t *tables) logDynamicReads(w io.Writer, reached, selected map[string]bool) {
	if w == nil || len(reached) == 0 {
		return
	}
	declared := map[string]map[string]bool{}
	for _, d := range t.dynReads {
		if declared[d.pkg] == nil {
			declared[d.pkg] = map[string]bool{}
		}
		for _, c := range d.classes {
			declared[d.pkg][c] = true
		}
	}
	var pkgs []string
	for p := range declared {
		pkgs = append(pkgs, p)
	}
	sort.Strings(pkgs)
	reach := sortedKeys(reached)
	for _, p := range pkgs {
		state := "not selected"
		if selected[p] {
			state = "selected"
		}
		fmt.Fprintf(w, "dynamic read in %s: classes declared %v, reachable %v; %s\n", p, sortedKeys(declared[p]), reach, state)
	}
}
